import { ApiError } from "../api-error.js";
import { readJsonBody } from "../body.js";
export function isRecord(value) {
    return typeof value === "object" && value !== null && !Array.isArray(value);
}
export function invalid(message, cause) {
    throw new ApiError(400, "invalid_request", message, {
        cause
    });
}
export async function readObject(request, label, maxBytes) {
    const value = await readJsonBody(request, maxBytes);
    if (!isRecord(value)) invalid(`${label} must be an object`);
    return value;
}
export function parseInput(parse) {
    try {
        return parse();
    } catch (error) {
        if (error instanceof ApiError) throw error;
        invalid(error instanceof Error ? error.message : "invalid request", error);
    }
}
export async function downstream(operation, action) {
    try {
        return await action();
    } catch (error) {
        if (error instanceof ApiError) throw error;
        throw new ApiError(502, "downstream_failure", `${operation} failed`, {
            cause: error
        });
    }
}
export function shouldRecord(value) {
    return !isRecord(value) || value.record !== false;
}
export function requiredString(value, name, maxLength = 512) {
    if (typeof value !== "string" || !value.trim()) invalid(`${name} is required`);
    const normalized = value.trim();
    if (normalized.length > maxLength) invalid(`${name} is too long`);
    return normalized;
}
